function createPalindromeRootElement(xPosition, yPosition, width, height, gap, leftMargin) {
    const parentElement = document.createElement('div');
    parentElement.setAttribute('id', 'palindrome');
    parentElement.style.position = 'absolute';
    parentElement.style.width = `calc(${width} - ${2 * gap}px)`;
    parentElement.style.height = `calc(${height} - ${2* gap}px)`;
    parentElement.style.left = `calc(${xPosition * 25}% + ${leftMargin}px)`;
    parentElement.style.top = `calc(${yPosition * 25}% + ${gap}px)`;
    parentElement.style.margin = `${gap}px`;
    parentElement.style.borderRadius = `5px`;
    parentElement.style.overflow = 'hidden';
    parentElement.style.border = '1px solid lightgrey';
    return parentElement;
}

function setPalindromeConfig(palindromeConfig, devConfig, data, gap, width, height, useCaseOptions) {
    Object.assign(palindromeConfig, devConfig);
    palindromeConfig.data = data;
    palindromeConfig.innerHeight = (window.innerHeight * parseInt(height) / 100) - (2 * gap);
    palindromeConfig.innerWidth = (window.innerWidth * parseInt(width) / 100) - (2 * gap);
    palindromeConfig.grafanaZoom = 1.5;
    palindromeConfig.disableZoom = true;
    Object.assign(palindromeConfig, useCaseOptions);
}

function createPanel(xPosition, yPosition, width, height, data, titleText, useCaseOptions, devConfig) {
    const palindromeComponent = createPalindrome(xPosition, yPosition, width, height, data, useCaseOptions, devConfig, titleText);
    const title = createPanelTitle(titleText);
    const note = createPanelNote();
    palindromeComponent.prepend(note);
    palindromeComponent.prepend(title);
    return palindromeComponent;
}

function createPalindrome(xPosition, yPosition, width, height, data, useCaseOptions, devConfig, titleText) {
    const validWidths = ['25%', '50%', '75%', '100%'];
    if (!validWidths.includes(width)) {
        console.error('Invalid width. Please use 25%, 50%, 75%, or 100%');
        return;
    }
    const validHeights = ['25%', '50%', '75%', '100%'];
    if (!validHeights.includes(height)) {
        console.error('Invalid height. Please use 25%, 50%, 75%, or 100%');
        return;
    }

    const gap = 10;
    const leftMargin = 0.5;
    const rootElement = createPalindromeRootElement(xPosition, yPosition, width, height, gap, leftMargin);
    const palindromeConfig = renderDev(true);
    palindromeConfig.title = titleText;
    setPalindromeConfig(palindromeConfig, devConfig, data, gap, width, height, useCaseOptions);
    palindrome(rootElement, palindromeConfig);
    return rootElement;
}

/**
 * Setup page layout.
 */
function setupLayout(isStorybook) {
    document.body.style.backgroundColor = '#f0f3f6';  
    if (!isStorybook)   {
        closeSidebar();
        if (process.env.PALINDROME_TYPE !== 'basic') {
            const header = document.createElement('div');
            header.style.height = '100px';
            document.body.appendChild(header);
        }
    }
}

/**
 * Creates Palindrome.js grid
 * @param {Object} devConfig the full palindrome.js configuration
 * @param {Boolean} benchmark A boolean to disable or enable benchmark
 * @param {Integer} useCaseIndex The index of the use case that we want to benchmark
 */
export function createGrid(isStorybook = false) {
    const grid = document.createElement('div');
    grid.id = 'grid-container';
    grid.style.width = `${isStorybook ? window.innerWidth + 'px' : '100%'}`;
    grid.style.height = `${isStorybook ? window.innerHeight + 'px' : '100%'}`;
    grid.style.position = 'relative';
    return grid;
}

/**
 * Main function to create grid use cases
 * @param {Object} devConfig 
 * @param {Boolean} benchmark 
 */
export function generatePalindromeViews(devConfig, benchmark, useCaseIndex = 1, isStorybook = false) {
    setupLayout(isStorybook);
    const grid = createGrid(isStorybook);
    for (let i = 0; i < devConfig.data.grid.length; i++) {
        const e = devConfig.data.grid[i];
        let data = e.data;
        if (benchmark && data.options) {
            if (i === useCaseIndex) {
                data.options.benchmarkDataUpdate = true;
            }
            data.options.liveData = true;
        }

        const useCaseOptions = e.useCaseOptions;
        const panel = createPanel(e.x, e.y, e.w, e.h ?? '50%', data, e.title, useCaseOptions, devConfig);
        grid.appendChild(panel);
    }
    return grid;
}

/**
 * Renders Palindrome with config
 */
export function renderDev(isGrafana) {
    if (isGrafana) {
        const devConfig = getDefaultValues();
        devConfig.isGrafana = isGrafana;
        return devConfig;
    }
    createSideBar();
    createSideBarContent();
    createCategories();
    appendControlsToCategories();
    init();
    const devConfig = getDefaultValues();
    applyParamsToConfig(devConfig);
    devConfig.isGrafana = isGrafana;
    const isMultipleViewPorts = applyDefaultOptions(devConfig);
    if (isMultipleViewPorts) {
        let multipleViewPortsLayout;
        if (process.env.CI_BENCHMARK === 'multi-viewports') {
            multipleViewPortsLayout = generatePalindromeViews(devConfig, true);
        }
        else {
            multipleViewPortsLayout = generatePalindromeViews(devConfig, false);
        }
        document.body.appendChild(multipleViewPortsLayout);
    }
    else {
        if (process.env.PALINDROME_TYPE === "basic" || process.env.PALINDROME_TYPE === "dev" || process.env.PALINDROME_BENCH_PALINDROME_TYPE) {
            getPalindrome(devConfig);
        }
        if (process.env.PALINDROME_TYPE === "dev" || process.env.PALINDROME_BENCH_PALINDROME_TYPE === 'dev') {
            applyConditionsToControls();
        }
    }
    return devConfig;
}